<template><ForgeDialog title="MySQL code maker" description="Connect to a MySQL server and inspect its available databases." eyebrow="WORKSPACE / DATABASES" @close="emit('close')"><div class="mysql-panel"><div class="mysql-grid"><label>User<input v-model="user" /></label><label>Password<input v-model="password" type="password" /></label><label>Host<input v-model="host" /></label><label>Port<input v-model.number="port" type="number" /></label></div><button class="primary-button" :disabled="loading" @click="connect">{{ loading?'Connecting…':'Connect' }}</button><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p><div v-if="databases.length" class="db-list"><b>Databases</b><code v-for="db in databases" :key="db">{{ db }}</code></div><p v-else class="empty-copy">Connect to load databases.</p></div></ForgeDialog></template>
<script setup lang="ts">
import { ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import IPC from '@/util/IPC'
const emit=defineEmits<{close:[]}>(); const user=ref('root'); const password=ref(''); const host=ref('127.0.0.1'); const port=ref(3306); const databases=ref<string[]>([]); const loading=ref(false); const error=ref(''); const connect=async()=>{loading.value=true;error.value='';try{await new Promise<void>((resolve,reject)=>{IPC.send('app-fork:codemake','connect',{user:user.value,password:password.value,host:host.value,port:port.value}).then((key:string,res:any)=>{IPC.off(key);res?.code===0?(databases.value=res.data??[],resolve()):reject(new Error(res?.msg??'MySQL connection failed'))})})}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
</script>
<style scoped>.mysql-panel{display:grid;gap:14px}.mysql-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mysql-grid label{display:grid;gap:6px;color:var(--pqt-text-muted);font-size:11px}.mysql-grid input{padding:9px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.db-list{display:grid;gap:6px;padding:12px;border:1px solid var(--pqt-border);border-radius:7px}.db-list code{padding:7px;background:var(--pqt-canvas);color:var(--pqt-text-muted);font:11px var(--pqt-font-mono)}</style>
